/**
 * The scorer on REAL captured turns (ids removed): its classification and its key
 * verdicts, plus the shared acceptance fixture's own consistency.
 *
 * Both fixtures are generated by build-fixtures.ts from construction-witness captures;
 * the builder already refuses a case whose stripped payload scores differently from the
 * full capture, so these files carry everything the scorer reads.
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { CHECK_NAMES } from '../src/checks.js';
import { CASE_CLASSES } from '../src/classify.js';
import { assertNoIds, scoreFixtureCase, type FixtureCase } from '../src/fixture.js';

const here = dirname(fileURLToPath(import.meta.url));
const load = (p: string): { cases: FixtureCase[]; builds: string[] } => JSON.parse(readFileSync(p, 'utf8'));
const real = load(join(here, 'fixtures', 'real-turns.json'));
const shared = load(join(here, '..', '..', '..', 'Docs', 'evals', 'agent-reply', 'fixtures', 'cases.json'));
const byId = (id: string): FixtureCase => real.cases.find((c) => c.id === id)!;

describe('real captured turns (served 8428207)', () => {
  it('has the three turns it claims, all from the current build', () => {
    expect(real.cases.map((c) => c.id)).toEqual(['real-run-near-tie', 'real-run-blocked', 'real-approval-chip']);
    expect(real.builds).toEqual(['8428207']);
  });

  it('typed Run on a near tie → run_leader_withheld, and the reply names a leader anyway', () => {
    const s = scoreFixtureCase(byId('real-run-near-tie'));
    expect(s.cls).toBe('run_leader_withheld');
    expect([s.facets.leaderPermitted, s.facets.withheldReason]).toEqual([false, 'options_do_not_separate']);
    expect(s.checks.LEADER_HONESTY.verdict).toBe('FAIL');
    expect(s.checks.LEADER_HONESTY.findings[0]?.excerpt).toContain('more likely to lead');
    expect(s.checks.CAVEAT.verdict).toBe('PASS');
    expect(s.observations.blockSummaryNamesLeaderWhileWithheld).toBe(true);
  });

  it('typed Run with the model not ready → run_blocked, caveat (did not run) present, one next-step chip', () => {
    const s = scoreFixtureCase(byId('real-run-blocked'));
    expect(s.cls).toBe('run_blocked');
    expect(s.facets.ranAnalysis).toBe(false);
    expect(s.checks.CAVEAT.verdict).toBe('PASS');
    expect(s.metrics.chipLabels).toEqual(['Suggest what it still needs']);
  });

  it('typed-chip approval → approval_chip, every word server-authored, the save it states is supported', () => {
    const s = scoreFixtureCase(byId('real-approval-chip'));
    expect(s.cls).toBe('approval_chip');
    expect([s.metrics.splitBasis, s.metrics.modelWordsEstimate]).toEqual(['fast_path_approve', 0]);
    expect(s.checks.ACTION_TRUTH.verdict).toBe('PASS');
    expect(s.checks.ACTION_TRUTH.vacuous).toBe(false);
  });

  it('the same payload read as a different user action classifies differently (the context matters)', () => {
    const c = byId('real-run-near-tie');
    expect(scoreFixtureCase({ ...c, context: { ...c.context, user_action: 'rerun', rerun_kind: 'no_change' } }).cls).toBe('rerun_no_change');
  });
});

describe('shared acceptance fixture (prompt/harness half)', () => {
  it('covers every run/approval/edit/follow-up class the baseline reports, one or two cases each', () => {
    const counts = new Map<string, number>();
    for (const c of shared.cases) counts.set(c.class, (counts.get(c.class) ?? 0) + 1);
    for (const cls of ['build_hiring', 'build_pricing', 'build_heldout', 'run_leader_permitted', 'run_leader_withheld', 'run_blocked', 'approval_chip', 'approval_typed', 'edit_no_run', 'rerun_after_edit', 'rerun_no_change', 'challenge', 'uncertainty_followup']) {
      expect([cls, counts.get(cls) ?? 0]).toEqual([cls, expect.any(Number)]);
      expect(counts.get(cls) ?? 0).toBeGreaterThanOrEqual(1);
      expect(counts.get(cls) ?? 0).toBeLessThanOrEqual(2);
    }
    for (const c of shared.cases) expect(CASE_CLASSES).toContain(c.class);
  });

  it('every case scores to its labelled class and reproduces its recorded served-reply verdicts', () => {
    for (const c of shared.cases) {
      const s = scoreFixtureCase(c);
      expect([c.id, s.cls]).toEqual([c.id, c.class]);
      expect([c.id, Object.fromEntries(CHECK_NAMES.map((k) => [k, s.checks[k].verdict]))]).toEqual([c.id, c.served_reply_verdicts]);
    }
  });

  it('expect blocks carry the prompt-side rules: ~90 soft words, ≤1 question, leader permission, caveat, forbidden claims', () => {
    for (const c of shared.cases) {
      expect(c.expect.max_words_default).toBe(90);
      expect(c.expect.words_soft).toBe(true);
      expect(c.expect.max_questions).toBe(1);
      expect(c.expect.forbidden_claims).toContain('promises_the_analysis_will_run_on_approval');
      if (c.expect.leader_may_be_named !== true) expect(c.expect.forbidden_claims).toContain('names_or_hints_a_leading_option');
    }
    const permitted = shared.cases.find((c) => c.id === 'run-leader-permitted')!;
    expect(permitted.expect.leader_may_be_named).toBe(true);
    expect(shared.cases.find((c) => c.id === 'run-leader-withheld-near-tie')!.expect.caveat_required).toBe(true);
  });

  it('carries no identifiers — and the guard does fire on one', () => {
    expect(() => assertNoIds(JSON.stringify(shared))).not.toThrow();
    expect(() => assertNoIds(JSON.stringify(real))).not.toThrow();
    expect(() => assertNoIds('{"x":"prop_0123456789abcdef"}')).toThrow(/identifier-like/);
    expect(() => assertNoIds('{"request_id":"r"}')).toThrow(/request_id/);
  });
});
